              ? 0.055
              : 0.008
          }
          polygonCapColor={(feature: object) =>
            (feature as CountryFeature).properties.iso_a3 ===
            hoveredCountry?.properties.iso_a3
              ? "rgba(255, 255, 255, 0.18)"
              : "rgba(255, 255, 255, 0.02)"
          }
          polygonSideColor={(feature: object) =>
