"use client";

import { useEffect, useRef } from "react";

type Panorama3DStageProps = {
  imagePaths: string[];
  fromIndex: number;
  toIndex: number;
  mixProgress: number;
  initialYaw?: number;
  initialPitch?: number;
  onReadyChange?: (isReady: boolean) => void;
};

function clamp(value: number, min: number, max: number) {
  return Math.min(Math.max(value, min), max);
}

export function Panorama3DStage({
  imagePaths,
  fromIndex,
  toIndex,
  mixProgress,
  initialYaw = -90,
  initialPitch = 0,
  onReadyChange
}: Panorama3DStageProps) {
  const mountRef = useRef<HTMLDivElement | null>(null);
  const materialRef = useRef<any>(null);
  const textureMapRef = useRef<Map<string, any>>(new Map());
  const animationFrameRef = useRef<number | null>(null);
  const latestBlendRef = useRef({
    imagePaths,
    fromIndex,
    toIndex,
    mixProgress
  });

  function applyBlend() {
    const material = materialRef.current;

    if (!material) {
      return;
    }

    const {
      imagePaths: currentImagePaths,
      fromIndex: currentFromIndex,
      toIndex: currentToIndex,
      mixProgress: currentMixProgress
    } = latestBlendRef.current;
    const textureMap = textureMapRef.current;
    const fallbackTexture =
      textureMap.get(currentImagePaths[0]) ?? Array.from(textureMap.values())[0] ?? null;
    const fromTexture =
      textureMap.get(currentImagePaths[currentFromIndex]) ?? fallbackTexture;
    const toTexture =
      textureMap.get(currentImagePaths[currentToIndex]) ?? fromTexture ?? fallbackTexture;

    if (!fromTexture || !toTexture) {
      return;
    }

    material.uniforms.textureFrom.value = fromTexture;
    material.uniforms.textureTo.value = toTexture;
    material.uniforms.mixProgress.value = clamp(currentMixProgress, 0, 1);
  }

  useEffect(() => {
    latestBlendRef.current = {
      imagePaths,
      fromIndex,
      toIndex,
      mixProgress
    };

    applyBlend();
  }, [fromIndex, imagePaths, mixProgress, toIndex]);

  useEffect(() => {
    const mount = mountRef.current;

    if (!mount) {
      return;
    }

    let isCancelled = false;
    let resizeObserver: ResizeObserver | null = null;
    let renderer: any = null;
    let geometry: any = null;
    let material: any = null;

    onReadyChange?.(false);

    async function setupScene() {
      const THREE = await import("three");

      if (isCancelled) {
        return;
      }

      const scene = new THREE.Scene();
      const camera = new THREE.PerspectiveCamera(75, 1, 0.1, 1100);

      renderer = new THREE.WebGLRenderer({
        antialias: true,
        alpha: true
      });
      renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));

      if ("outputColorSpace" in renderer && THREE.SRGBColorSpace) {
        renderer.outputColorSpace = THREE.SRGBColorSpace;
      } else {
        renderer.outputEncoding = THREE.sRGBEncoding;
      }

      renderer.setClearColor(0x000000, 0);
      renderer.domElement.setAttribute("aria-hidden", "true");
      renderer.domElement.style.display = "block";
      renderer.domElement.style.height = "100%";
      renderer.domElement.style.width = "100%";
      renderer.domElement.style.pointerEvents = "none";
      mount.appendChild(renderer.domElement);

      geometry = new THREE.SphereGeometry(500, 96, 64);
      geometry.scale(-1, 1, 1);

      material = new THREE.ShaderMaterial({
        uniforms: {
          textureFrom: { value: null },
          textureTo: { value: null },
          mixProgress: { value: 0 }
        },
        vertexShader: `
          varying vec2 vUv;

          void main() {
            vUv = uv;
            gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
          }
        `,
        fragmentShader: `
          uniform sampler2D textureFrom;
          uniform sampler2D textureTo;
          uniform float mixProgress;
          varying vec2 vUv;

          void main() {
            vec4 fromColor = texture2D(textureFrom, vUv);
            vec4 toColor = texture2D(textureTo, vUv);
            gl_FragColor = mix(fromColor, toColor, clamp(mixProgress, 0.0, 1.0));
          }
        `
      });

      materialRef.current = material;

      const mesh = new THREE.Mesh(geometry, material);
      scene.add(mesh);

      const loader = new THREE.TextureLoader();
      const uniqueImagePaths = Array.from(new Set(imagePaths));

      const textureEntries = await Promise.all(
        uniqueImagePaths.map(
          (imagePath) =>
            new Promise<[string, any | null]>((resolve) => {
              loader.load(
                imagePath,
                (texture) => resolve([imagePath, texture]),
                undefined,
                () => resolve([imagePath, null])
              );
            })
        )
      );

      if (isCancelled) {
        textureEntries.forEach(([, texture]) => {
          texture?.dispose?.();
        });
        return;
      }

      textureMapRef.current = new Map();

      textureEntries.forEach(([imagePath, texture]) => {
        if (!texture) {
          return;
        }

        if ("colorSpace" in texture && THREE.SRGBColorSpace) {
          texture.colorSpace = THREE.SRGBColorSpace;
        } else {
          texture.encoding = THREE.sRGBEncoding;
        }

        texture.minFilter = THREE.LinearFilter;
        texture.magFilter = THREE.LinearFilter;
        textureMapRef.current.set(imagePath, texture);
      });

      applyBlend();
      onReadyChange?.(textureMapRef.current.size > 0);

      const phi = THREE.MathUtils.degToRad(90 - initialPitch);
      const theta = THREE.MathUtils.degToRad(initialYaw);

      camera.lookAt(
        500 * Math.sin(phi) * Math.cos(theta),
        500 * Math.cos(phi),
        500 * Math.sin(phi) * Math.sin(theta)
      );

      resizeObserver = new ResizeObserver(([entry]) => {
        const { width, height } = entry.contentRect;

        if (!width || !height || !renderer) {
          return;
        }

        renderer.setSize(width, height, false);
        camera.aspect = width / height;
        camera.updateProjectionMatrix();
      });

      resizeObserver.observe(mount);

      function animate() {
        if (!renderer) {
          return;
        }

        renderer.render(scene, camera);
        animationFrameRef.current = window.requestAnimationFrame(animate);
      }

      animate();
    }

    void setupScene();

    return () => {
      isCancelled = true;
      onReadyChange?.(false);

      if (animationFrameRef.current) {
        window.cancelAnimationFrame(animationFrameRef.current);
        animationFrameRef.current = null;
      }

      resizeObserver?.disconnect();
      textureMapRef.current.forEach((texture) => {
        texture?.dispose?.();
      });
      textureMapRef.current.clear();
      materialRef.current = null;
      material?.dispose?.();
      geometry?.dispose?.();

      if (renderer) {
        renderer.dispose();
        renderer.domElement.remove();
      }
    };
  }, [imagePaths, initialPitch, initialYaw, onReadyChange]);

  return <div ref={mountRef} className="absolute inset-0" />;
}

