    const drum = drumRef.current;
    if (!drum) return;

    function handleWheel(event: WheelEvent) {
      event.preventDefault();
      if (wheelLock.current) return;

      select(index + (event.deltaY > 0 ? 1 : -1));
      wheelLock.current = true;
      window.setTimeout(() => {
        wheelLock.current = false;
      }, WHEEL_LOCK_MS);
